ALTER TABLE prd_schema RENAME TO prd_schema_v3;
CREATE TABLE prd_schema(version INTEGER NOT NULL CHECK(version=4));
INSERT INTO prd_schema VALUES(4);
DROP TABLE prd_schema_v3;
CREATE TABLE prd_settings(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE prd_schedules(object_kind TEXT NOT NULL,object_id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(object_kind,object_id));
CREATE TABLE prd_schedule_revisions(object_kind TEXT NOT NULL,object_id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(object_kind,object_id,version));
CREATE TABLE prd_feedback(id TEXT PRIMARY KEY,knowledge_id TEXT NOT NULL,source_kind TEXT NOT NULL,source_id TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,UNIQUE(knowledge_id,source_kind,source_id));
CREATE TABLE prd_feedback_revisions(event_id TEXT NOT NULL REFERENCES prd_feedback(id),version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(event_id,version));
CREATE TABLE prd_annotations(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES prd_feedback(id),data TEXT NOT NULL);
CREATE TABLE prd_reviews(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL,object_id TEXT NOT NULL,generation INTEGER NOT NULL,due_date TEXT NOT NULL,version INTEGER NOT NULL,data TEXT NOT NULL,UNIQUE(object_kind,object_id,generation,due_date));
CREATE TABLE prd_review_revisions(review_id TEXT NOT NULL REFERENCES prd_reviews(id),version INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(review_id,version));
CREATE TABLE prd_knowledge_v4(id TEXT PRIMARY KEY,source_lesson_id TEXT REFERENCES prd_lessons(id),source_session_id TEXT REFERENCES prd_sessions(id),source_event_id TEXT REFERENCES prd_feedback(id),source_review_id TEXT REFERENCES prd_reviews(id),data TEXT NOT NULL,CHECK((source_lesson_id IS NOT NULL)+(source_session_id IS NOT NULL)+(source_event_id IS NOT NULL)+(source_review_id IS NOT NULL)<=1));
INSERT INTO prd_knowledge_v4(id,source_lesson_id,source_session_id,data) SELECT id,source_lesson_id,source_session_id,data FROM prd_knowledge;
DROP TABLE prd_knowledge;
ALTER TABLE prd_knowledge_v4 RENAME TO prd_knowledge;
CREATE TABLE prd_actions_v4(id TEXT PRIMARY KEY,source_lesson_id TEXT REFERENCES prd_lessons(id),source_session_id TEXT REFERENCES prd_sessions(id),source_event_id TEXT REFERENCES prd_feedback(id),source_review_id TEXT REFERENCES prd_reviews(id),data TEXT NOT NULL,CHECK((source_lesson_id IS NOT NULL)+(source_session_id IS NOT NULL)+(source_event_id IS NOT NULL)+(source_review_id IS NOT NULL)<=1));
INSERT INTO prd_actions_v4(id,source_lesson_id,source_session_id,data) SELECT id,source_lesson_id,source_session_id,data FROM prd_actions;
DROP TABLE prd_actions;
ALTER TABLE prd_actions_v4 RENAME TO prd_actions;
